const PAD = 56;
const MONO = 'JetBrains Mono';

function scrims() {
  return `<defs>` +
    `<radialGradient id="scrim-top" cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform="translate(0 0) scale(470 230)">` +
    `<stop offset="0" stop-color="${THEME.bg}" stop-opacity="0.85"/><stop offset="1" stop-color="${THEME.bg}" stop-opacity="0"/></radialGradient>` +
    `<radialGradient id="scrim-foot" cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform="translate(0 ${OG_HEIGHT}) scale(640 380)">` +
    `<stop offset="0" stop-color="${THEME.bg}" stop-opacity="0.92"/><stop offset="0.55" stop-color="${THEME.bg}" stop-opacity="0.7"/><stop offset="1" stop-color="${THEME.bg}" stop-opacity="0"/></radialGradient>` +
    `</defs>` +
    `<rect width="${OG_WIDTH}" height="${OG_HEIGHT}" fill="url(#scrim-top)"/>` +
    `<rect width="${OG_WIDTH}" height="${OG_HEIGHT}" fill="url(#scrim-foot)"/>`;
}

function brand() {
  const markSize = 40;
  const markScale = markSize / 282;
  return `<g transform="translate(${PAD} 46) scale(${markScale.toFixed(4)}) translate(-243 -243)">` +
    `<path d="${LOGO_PATH}" fill="${THEME.paper}"/></g>` +
    `<path transform="translate(${PAD + markSize + 11} 77)" d="${WORDMARK_PATH}" fill="${THEME.paper}"/>` +
    `<text x="${OG_WIDTH - PAD}" y="76" text-anchor="end" font-family="${MONO}" font-size="22" fill="${THEME.muted}">ratspeak.org</text>`;
}

// Bottom-left, left of x=285: a centred square crop shows only the map.
function caption() {
  const lead = 83;
  const lastBaseline = OG_HEIGHT - 50;
  return HEADLINE.map((d, i) => {
    const y = lastBaseline - (HEADLINE.length - 1 - i) * lead;
    return `<path transform="translate(${PAD} ${y})" d="${d}" fill="${THEME.paper}"/>`;
  }).join('');
}

export function buildMapSvg(snapshot, { land, countries } = {}) {
  const nodes = plottableNodes(snapshot);
  return `<svg width="${OG_WIDTH}" height="${OG_HEIGHT}" viewBox="0 0 ${OG_WIDTH} ${OG_HEIGHT}" xmlns="http://www.w3.org/2000/svg">` +
    `<rect width="${OG_WIDTH}" height="${OG_HEIGHT}" fill="${THEME.bg}"/>` +
    (land ? `<path d="${geojsonToPath(land)}" fill="${THEME.land}" stroke="${THEME.coast}" stroke-width="0.7" fill-rule="evenodd"/>` : '') +
    (countries ? `<path d="${geojsonToPath(countries)}" fill="none" stroke="${THEME.border}" stroke-width="0.6"/>` : '') +
    scrims() +
    nodeDots(nodes) +
    brand() +
    caption() +
    `</svg>`;
}
